(window.FREALLY_I18N = window.FREALLY_I18N || {})["hi"] = {"hero.headline":"<span class=\"hl-muted\">आपकी फ़ाइलें, बाइट-दर-बाइट।</span> <span class=\"cycle\" data-cycle=\"hero.cycle\">कॉपी की गईं।</span>","hero.cycle":"कॉपी की गईं।|मूव की गईं।|सिंक की गईं।|सत्यापित की गईं।","hero.sub":"Windows, macOS और Linux के लिए एक डेस्कटॉप फ़ाइल कॉपियर, जिसमें चेकसम सत्यापन, क्रैश के बाद फिर से शुरू करना, दोतरफ़ा सिंक, पूर्ववत करना और अपना ख़ुद का फ़ाइल सर्वर है। कोई खाता नहीं, कोई टेलीमेट्री नहीं और कोई AI नहीं।","hero.chipLanguages":"18 भाषाएँ","hero.chipCli":"कमांड लाइन","what.title":"यह क्या है","what.p1":"अपने सिस्टम के अपने कॉपी डायलॉग से कोई बड़ा फ़ोल्डर कॉपी करने पर आपको बहुत कम पता चलता है: न कोई चेकसम, न पहले से मौजूद फ़ाइलों के साथ क्या हो इस पर आपकी कोई राय, और आधे रास्ते में बिजली चली जाए तो वापसी का कोई रास्ता नहीं।","what.p2":"Freally File Manager एक ऐसा कॉपियर है जिसे इसी काम के लिए भरोसे लायक बनाया गया है। उसकी विंडो पर फ़ाइलें छोड़ें, एक गंतव्य चुनें, और वह उन्हें आपके सिस्टम के सबसे तेज़ कॉपी रास्ते से कॉपी करता है। सत्यापन चालू करें और वह हर कॉपी को दोबारा पढ़कर मूल फ़ाइल के चेकसम से मिलाता है।","what.p3":"कॉपियर के इर्द-गिर्द वह सब कुछ है जिसकी ज़रूरत आपको बाद में पड़ती है: हर कार्य का इतिहास, दोबारा चलाने और पूर्ववत करने की सुविधा के साथ, चेकसम टूल, दोतरफ़ा सिंक और लाइव मिरर, स्नैपशॉट, एक बिल्ट-इन फ़ाइल सर्वर और स्क्रिप्ट के लिए कमांड लाइन।","features.title":"इसमें क्या है","features.copy.title":"बाइट-दर-बाइट सटीक कॉपियाँ","features.copy.body":"हर फ़ाइल आपके सिस्टम के अपने तेज़ रास्तों से बाइट-दर-बाइट कॉपी होती है, और जिन ड्राइव पर यह सुविधा है उन पर तुरंत क्लोन हो जाती है। किसी भी कार्य को रोकें, जारी रखें या रद्द करें, और शुरू होने से पहले तय करें कि किसी फ़ाइल के पहले से मौजूद होने पर क्या हो।","features.verify.title":"जब आप कहें, तब सत्यापित","features.verify.body":"सत्यापन चालू करें और हर कॉपी को दोबारा पढ़कर आठ चेकसम में से किसी एक से मूल फ़ाइल के साथ मिलाया जाता है, CRC32 और xxHash3 से लेकर SHA-256 और BLAKE3 तक। कोई भी बेमेल बताया जाता है, कभी छिपाया नहीं जाता।","features.resume.title":"बिजली जाने पर भी टिका रहता है","features.resume.body":"एक जर्नल दर्ज करता है कि हर कॉपी कहाँ तक पहुँची। क्रैश या रीबूट के बाद, पहले से लिखे गए हिस्से की जाँच होती है और कॉपी फिर से शुरू होने के बजाय वहीं से आगे बढ़ती है।","features.sync.title":"दोतरफ़ा सिंक","features.sync.body":"दो फ़ोल्डरों को दोनों दिशाओं में एक जैसा रखें, या एक को दूसरे पर मिरर करें। दोनों तरफ़ बदली गई फ़ाइल एक टकराव है: दोनों संस्करण रखे जाते हैं और चुनाव आप करते हैं।","features.history.title":"इतिहास और पूर्ववत","features.history.body":"हर कार्य दर्ज होता है। उसे फिर से चलाएँ, केवल विफल फ़ाइलों का पुनः प्रयास करें, या आख़िरी कॉपी या मूव को पूर्ववत करें: पूर्ववत की गई कॉपियाँ रीसायकल बिन या ट्रैश में जाती हैं, सीधे कभी नहीं मिटाई जातीं।","features.checks.title":"अपनी फ़ाइलें कभी भी जाँचें","features.checks.body":"किसी भी फ़ाइल का हैश आठ चेकसम से निकालें, .sha256 या .sfv फ़ाइलें बनाएँ और जाँचें, महीनों बाद किसी फ़ोल्डर की उसकी कॉपी से तुलना करें, और जो कॉपी हुआ उसकी एक हस्ताक्षरित रिपोर्ट निर्यात करें।","features.server.title":"आपका अपना फ़ाइल सर्वर","features.server.body":"किसी फ़ोल्डर को दूसरे कंप्यूटरों के लिए WebDAV, सादे HTTP, S3-संगत API या SFTP पर उपलब्ध कराएँ, चाहें तो केवल पढ़ने के लिए, पासवर्ड या टोकन के पीछे।","features.free.title":"मुफ़्त, निजी, बिना AI","features.free.body":"कोई खाता नहीं, कोई टेलीमेट्री नहीं और कोई मशीन लर्निंग नहीं। आपकी फ़ाइलें केवल वहीं जाती हैं जहाँ आप उन्हें भेजते हैं, और रोज़ाना की अपडेट जाँच बंद की जा सकती है।","ladder.title":"1.0 की ओर रास्ता","ladder.intro":"हर संस्करण के लिए एक पंक्ति, सबसे पुराना पहले। इनमें से हर एक पूरा हो चुका है: बनाया गया, परखा गया और टैग किया गया।","ladder.rung.v0.19.84":"पहली रिलीज़: वैकल्पिक सत्यापन के साथ बाइट-दर-बाइट सटीक कॉपियाँ, क्रैश के बाद फिर से शुरू करना, इतिहास, दोतरफ़ा सिंक और लाइव मिरर, फ़ाइल सर्वर और कमांड लाइन, 18 भाषाओं में।","ladder.rung.v0.19.85":"लाइब्रेरी: डिडुप्लिकेट किए गए स्नैपशॉट, जिनका आप बैकअप ले सकते हैं, जिनकी तुलना कर सकते हैं और जिन्हें पुनर्स्थापित कर सकते हैं, और ऐसी रिपॉज़िटरी जिन्हें आप restic, Borg और Kopia से ला सकते हैं या उनमें निर्यात कर सकते हैं।","ladder.rung.v0.20.0":"सुरक्षा जाल: आख़िरी कॉपी या मूव को पूर्ववत करना, रीसायकल बिन या ट्रैश में हटाना, केवल विफल फ़ाइलों का पुनः प्रयास, चेकसम फ़ाइलें, और कार्य पूरा होने पर ड्राइव निकालना।","ladder.rung.v0.22.0":"हैशिंग, रिपोर्ट और शेड्यूलिंग: एक हैश निरीक्षक, हस्ताक्षरित कॉपी रिपोर्ट, पुनः सत्यापन, क्षतिग्रस्त मीडिया से बचाव, शेड्यूल, पसंदीदा, पोर्टेबल मोड और सुलभता।","ladder.rung.v1.0.0":"शुद्धता वाली रिलीज़: कोड की पूरी समीक्षा, खंड-दर-खंड, और उससे निकला हर सुधार।","ladder.note":"पूरा हुआ संस्करण बनाया और टैग किया जा चुका है। इनमें से कोई भी इस साइट पर डाउनलोड के लिए नहीं है: यहाँ अभी कोई डाउनलोड नहीं है।","honest.title":"वे बातें जिन्हें ज़्यादातर साइटें सबसे नीचे रखती हैं","honest.verify.title":"जब तक आप चालू न करें, सत्यापन बंद रहता है","honest.verify.body":"किसी कॉपी की जाँच का मतलब है उसे दूसरी बार पढ़ना, इसलिए यह डिफ़ॉल्ट नहीं बल्कि एक सेटिंग है। सेटिंग्स → स्थानांतरण में एक चेकसम चुनें, और उसके बाद की हर कॉपी जाँची जाती है।","honest.notYet.title":"दो काम जो 1.0 अभी नहीं कर सकता","honest.notYet.body":"यह फ़ाइलों को सुरक्षित रूप से श्रेड नहीं कर सकता, और क्लाउड स्टोरेज पर कॉपी नहीं कर सकता। सेटिंग्स में दोनों के लिए जगह पहले से है, लेकिन संस्करण 1.0.0 में इनमें से कोई भी जुड़ा नहीं है।","honest.network.title":"यह ऑनलाइन कब जाता है","honest.network.body":"आपकी अपनी ड्राइव के बीच कॉपी करना, सत्यापन और हटाना कोई नेटवर्क अनुरोध नहीं करते। यह उन चीज़ों के लिए ऑनलाइन जाता है जिन्हें आप सेट करते हैं, जैसे फ़ाइल सर्वर या किसी क्लाउड खाते की जाँच, और शुरू होने पर अपडेट जाँचने के लिए, दिन में अधिकतम एक बार, जिसे आप सेटिंग्स → अपडेट में बंद कर सकते हैं।","honest.downloads.title":"यहाँ अभी कोई डाउनलोड नहीं है","honest.downloads.body":"इस साइट पर न कोई इंस्टॉलर है, न प्रीव्यू बिल्ड, न कोई डाउनलोड लिंक। जब यह बदलेगा, यह पेज बताएगा।","site.tagline":"अपनी फ़ाइलें कॉपी करें, मूव करें, सिंक करें और सत्यापित करें, बाइट-दर-बाइट।","footer.licence":"स्वामित्व वाला — सर्वाधिकार सुरक्षित। © Mike Weaver. आज उपयोग के लिए मुफ़्त; भविष्य के संस्करण बेचे जा सकते हैं। ओपन सोर्स नहीं।","footer.yours":"आप जो फ़ाइलें कॉपी, सिंक और सर्व करते हैं, वे आपकी ही रहती हैं। Freally File Manager के लेखक उन पर किसी स्वामित्व का दावा नहीं करते।","featuresPage.lead":"सत्यापन, क्रैश के बाद फिर से शुरू करने, सिंक, पूर्ववत और अपने ख़ुद के फ़ाइल सर्वर वाला एक बाइट-दर-बाइट सटीक फ़ाइल कॉपियर, जो अपने चलाए हर कार्य का रिकॉर्ड भी रखता है।","featuresPage.version":"यह पेज Freally File Manager के संस्करण 1.0.0, यानी मौजूदा संस्करण, का वर्णन करता है: इसमें लिखी हर चीज़ 1.0.0 में है।","featuresPage.numbers.intro":"हर आँकड़ा संस्करण 1.0.0 के अपने कोड से गिना गया है। कुछ भी बढ़ाकर गोल नहीं किया गया है।","featuresPage.numbers.hashes":"कॉपी को सत्यापित करने के लिए चेकसम","featuresPage.numbers.collisions":"पहले से मौजूद फ़ाइल के लिए विकल्प","featuresPage.numbers.sidecars":"चेकसम-फ़ाइल फ़ॉर्मैट जिन्हें यह लिखता और जाँचता है","featuresPage.numbers.server":"फ़ोल्डर सर्व करने के तरीक़े: WebDAV, HTTP, S3 और SFTP","featuresPage.numbers.systems":"ऑपरेटिंग सिस्टम: Windows, macOS और Linux","featuresPage.numbers.languages":"भाषाएँ","featuresPage.numbers.ai":"AI मॉडल","featuresPage.numbers.price":"आज की क़ीमत","featuresPage.free.title":"आज मुफ़्त","featuresPage.free.body":"Freally File Manager आज जो कुछ भी करता है, वह सबके लिए मुफ़्त है: कोई पेड टियर नहीं, कोई सदस्यता नहीं, कोई लाइसेंस कुंजी नहीं और कोई खाता नहीं।","featuresPage.cards.title":"संस्करण 1.0 क्या करता है","featuresPage.cards.copy.title":"कॉपी इंजन","featuresPage.cards.copy.body":"हर सिस्टम के सबसे तेज़ रास्ते से बाइट-दर-बाइट सटीक कॉपियाँ, और जिन फ़ाइल सिस्टम में यह सुविधा है उन पर तुरंत क्लोन। विशाल फ़ोल्डर मेमोरी भरे बिना प्रवाहित होते हैं, और कॉपी शुरू होने से पहले आप चुनते हैं कि पहले से मौजूद फ़ाइलों का क्या हो: दोनों रखें, छोड़ें, ओवरराइट करें, नई होने पर ओवरराइट करें, केवल अलग होने पर ओवरराइट करें, या पूछें।","featuresPage.cards.verify.title":"कॉपी के बाद सत्यापित करें","featuresPage.cards.verify.body":"आठ चेकसम: CRC32, MD5, SHA-1, SHA-256, SHA-512, xxHash3-64, xxHash3-128 और BLAKE3। हर कॉपी दोबारा पढ़कर मूल से मिलाई जाती है, और बेमेल होने पर फ़ाइल चुपचाप पास होने के बजाय विफल हो जाती है।","featuresPage.cards.checks.title":"हैश, पुनः सत्यापन और चेकसम फ़ाइलें","featuresPage.cards.checks.body":"“हैश” पैनल फ़ाइलों को आपके पेस्ट किए चेकसम से जाँचता है। “पुनः सत्यापित करें” महीनों बाद किसी फ़ोल्डर की उसकी कॉपी से तुलना करता है, एक भी बाइट लिखे बिना। पूरे फ़ोल्डर के लिए .md5, .sha1, .sha256, .sha512, .b3 या .sfv फ़ाइलें बनाएँ, और जाँचने के लिए उनमें से किसी को विंडो पर छोड़ें।","featuresPage.cards.resume.title":"क्रैश और रीबूट के बाद फिर से शुरू","featuresPage.cards.resume.body":"एक जर्नल हर कॉपी की प्रगति दर्ज करता है। अगली बार ऐप खुलने पर पहले से लिखे गए हिस्से को उसके हैश से जाँचा जाता है, और कॉपी वहीं से आगे बढ़ती है।","featuresPage.cards.history.title":"इतिहास, दोबारा चलाना और पूर्ववत","featuresPage.cards.history.body":"हर कार्य दर्ज होता है। उनमें से किसी को भी फिर से चलाएँ, केवल विफल फ़ाइलों का पुनः प्रयास करें, एक हस्ताक्षरित रिपोर्ट निर्यात करें, या आख़िरी कॉपी या मूव को पूर्ववत करें: पूर्ववत की गई कॉपियाँ रीसायकल बिन या ट्रैश में जाती हैं, सीधे कभी नहीं मिटाई जातीं।","featuresPage.cards.sync.title":"सिंक और लाइव मिरर","featuresPage.cards.sync.body":"दोतरफ़ा सिंक, किसी भी दिशा में मिरर, या केवल योगदान, और टकराव दो फ़ाइलों के रूप में रखे जाते हैं ताकि आप उनमें से चुन सकें। लाइव मिरर किसी फ़ोल्डर पर नज़र रखता है और आपके सहेजे हर बदलाव को सिंक करता है।","featuresPage.cards.server.title":"एक बिल्ट-इन फ़ाइल सर्वर","featuresPage.cards.server.body":"किसी भी फ़ोल्डर को WebDAV, HTTP, S3-संगत API या SFTP पर सर्व करें, सेटिंग्स से या freally serve कमांड से, चाहें तो केवल पढ़ने के लिए, टोकन या पासवर्ड के पीछे, Prometheus मेट्रिक्स एंडपॉइंट के साथ।","featuresPage.cards.library.title":"स्नैपशॉट और बैकअप","featuresPage.cards.library.body":"एक डिडुप्लिकेट करने वाली रिपॉज़िटरी किसी फ़ाइल के हर संस्करण को एक ही बार संग्रहित करती है। टाइमलाइन ब्राउज़ करें, कोई भी स्नैपशॉट पुनर्स्थापित करें, चुने हुए फ़ोल्डरों का माँग पर बैकअप लें, और restic, Borg या Kopia से रिपॉज़िटरी लाएँ।","featuresPage.cards.salvage.title":"ख़राब होती डिस्क से बचाव","featuresPage.cards.salvage.body":"“बचाव” ख़राब होती ड्राइव पर किसी फ़ाइल का जितना हिस्सा अब भी पढ़ा जा सकता है, उसे कॉपी करता है, न पढ़े जा सकने वाले हिस्सों को शून्यों से भर देता है ताकि बाक़ी हिस्सा अपनी जगह पर रहे, अंतरालों का नक्शा रखता है, और अगली बार केवल उन्हीं अंतरालों का पुनः प्रयास करता है।","featuresPage.cards.metadata.title":"चुपचाप कुछ नहीं खोता","featuresPage.cards.metadata.body":"स्पार्स फ़ाइलें स्पार्स ही रहती हैं, और वैकल्पिक डेटा स्ट्रीम, विस्तारित एट्रिब्यूट और इंटरनेट-से-डाउनलोड का निशान हर फ़ाइल के साथ जाते हैं। Windows पर किसी दूसरे प्रोग्राम द्वारा लॉक की गई फ़ाइल को स्नैपशॉट से कॉपी किया जा सकता है।","featuresPage.cards.desktop.title":"आपके डेस्कटॉप का हिस्सा","featuresPage.cards.desktop.body":"Explorer, Finder, Nautilus, Dolphin और Thunar के राइट-क्लिक मेनू से कॉपी और मूव करें, Ctrl+Shift+V से कहीं से भी इसके ज़रिए पेस्ट करें, और सहेजे गए कार्यों को अपने सिस्टम के अपने शेड्यूलर में शेड्यूल करें।","featuresPage.cards.cli.title":"स्क्रिप्ट के लिए कमांड लाइन","featuresPage.cards.cli.body":"freally कमांड कॉपी, मूव और सत्यापन करता है, किसी कार्य को चलाने से पहले उसकी योजना बनाता है, फ़ोल्डर सर्व करता है और बैकअप आयात करता है, और प्रलेखित एग्ज़िट कोड के साथ JSON लाइनों में रिपोर्ट देता है।","featuresPage.compare.title":"व्यावसायिक औज़ारों के साथ आमने-सामने","featuresPage.compare.intro":"Freally File Manager 1.0.0 उन छह व्यावसायिक टूल के साथ, जिन्हें लोग अपनी फ़ाइलें कॉपी करने, जाँचने, सिंक करने और प्रबंधित करने के लिए ख़रीदते हैं। किसी दूसरे उत्पाद का हर ख़ाना उसके निर्माता के अपने पेजों से लिया गया है, जिन्हें 2 अक्टूबर 2026 को जाँचा गया, और क़ीमतें अक्टूबर 2026 की अमेरिकी सूची क़ीमतें हैं।","featuresPage.compare.feature":"फ़ीचर","featuresPage.compare.row.price":"क़ीमत (USD, अक्टूबर 2026)","featuresPage.compare.freeToday":"आज मुफ़्त","featuresPage.compare.legend.unknown":"सत्यापित नहीं","featuresPage.compare.note.aud":"ऑस्ट्रेलियाई डॉलर में बिकता है","featuresPage.compare.note.eur":"यूरो में बिकता है","featuresPage.compare.note.updatesYear":"एक साल के अपडेट","featuresPage.compare.note.perYear":"प्रति वर्ष, अधिकतम पाँच डिवाइस","featuresPage.compare.row.verify":"हर कॉपी को चेकसम से जाँचता है","featuresPage.compare.legend.yes":"उपलब्ध","featuresPage.compare.note.optional":"वैकल्पिक, आठ चेकसम","featuresPage.compare.legend.partly":"आंशिक","featuresPage.compare.note.checksumTool":"एक चेकसम टूल, हर कॉपी के बाद नहीं","featuresPage.compare.row.systems":"Windows, macOS और Linux","featuresPage.compare.note.oldMac":"Mac ऐप पुराना है","featuresPage.compare.note.webLinux":"Linux: केवल वेब इंटरफ़ेस","featuresPage.compare.row.resume":"क्रैश या रीबूट के बाद कॉपी फिर से शुरू करता है","featuresPage.compare.note.afterStop":"रुकने के बाद, सूची दोबारा खोलकर","featuresPage.compare.note.ftpOnly":"केवल FTP","featuresPage.compare.note.ftpDownloads":"केवल FTP डाउनलोड","featuresPage.compare.note.connectOnly":"केवल GoodSync Connect ट्रांसफ़र","featuresPage.compare.row.sync":"दोतरफ़ा सिंक जो टकराव के दोनों पक्ष रखता है","featuresPage.compare.note.byDate":"दोतरफ़ा, तारीख़ के आधार पर","featuresPage.compare.note.noConflicts":"दोतरफ़ा; टकराव प्रलेखित नहीं","featuresPage.compare.note.newerWins":"नई फ़ाइल जीतती है","featuresPage.compare.row.server":"WebDAV, S3 या SFTP पर फ़ोल्डर सर्व करता है","featuresPage.compare.note.ownProtocol":"केवल दूसरे GoodSync ऐप्स के लिए","featuresPage.compare.row.undo":"पूरी हो चुकी कॉपी या मूव को पूर्ववत करता है","featuresPage.compare.note.keepsVersions":"बदली गई फ़ाइलें रखता है","featuresPage.compare.row.salvage":"ख़राब होती ड्राइव से जो अब भी पढ़ा जा सकता है, उसे बचाता है","featuresPage.compare.row.report":"हर फ़ाइल के चेकसम की रिपोर्ट निर्यात करता है","featuresPage.compare.note.signable":"हस्ताक्षरित की जा सकती है","featuresPage.compare.note.logNoSums":"चेकसम के बिना एक लॉग","featuresPage.compare.note.logView":"एक लॉग व्यू","featuresPage.compare.note.compareReport":"एक अलग तुलना रिपोर्ट","featuresPage.compare.note.changeReport":"लॉग और एक बदलाव रिपोर्ट","featuresPage.compare.legend.no":"उपलब्ध नहीं","featuresPage.compare.summaryTitle":"संक्षेप में","featuresPage.compare.summary":"संक्षेप में: यह सब केवल Freally File Manager में है। छह में से कोई भी अपने निर्माता के अपने पेजों पर WebDAV, S3 या SFTP के लिए सर्वर, या ख़राब होती ड्राइव से फ़ाइलें बचाने का कोई तरीक़ा नहीं बताता, और छह में से केवल GoodSync सिंक टकराव का पता लगाने को प्रलेखित करता है।","featuresPage.compare.theyWinTitle":"जहाँ वे आगे हैं","featuresPage.compare.theyWin":"जहाँ वे आगे हैं: Directory Opus, Total Commander और ForkLift आपको अपने सभी फ़ोल्डर उनकी अपनी विंडो में ब्राउज़ और व्यवस्थित करने देते हैं, जबकि Freally File Manager 1.0.0 उन फ़ाइलों पर काम करता है जो आप उसे सौंपते हैं। TeraCopy और Directory Opus फ़ाइलों को सुरक्षित रूप से हटा सकते हैं, और ForkLift, Beyond Compare और GoodSync क्लाउड स्टोरेज पर कॉपी करते हैं; Freally File Manager 1.0.0 इनमें से कुछ भी नहीं करता। TeraCopy ज़्यादा चेकसम भी देता है: आठ के मुक़ाबले 17।","featuresPage.compare.asOf":"Freally File Manager का कॉलम संस्करण 1.0.0 का है, और इसकी क़ीमत आज की है: यह आज मुफ़्त है, और भविष्य के संस्करण बेचे जा सकते हैं। दूसरे उत्पाद भी बदलते हैं; यह तालिका 2 अक्टूबर 2026 तक की है।","featuresPage.why.title":"यह ऐसे क्यों बना है","featuresPage.why.exact.title":"बाइट-दर-बाइट, वरना विफल","featuresPage.why.exact.body":"कॉपी में वही बाइट होते हैं जो मूल में हैं, वरना उसे विफल बताया जाता है। और पढ़े जाते समय बदल जाने वाली फ़ाइल को, आपकी पसंद के अनुसार, चिह्नित किया जाता है, फिर से कॉपी किया जाता है या विफल किया जाता है, न कि साफ़ कॉपी बताकर आगे बढ़ा दिया जाता है।","featuresPage.why.native.title":"सिस्टम के अपने तेज़ रास्ते","featuresPage.why.native.body":"यह Windows, macOS और Linux से हर फ़ाइल को उनके जाने सबसे तेज़ तरीक़े से कॉपी करने को कहता है, और जहाँ फ़ाइल सिस्टम अनुमति दे वहाँ फ़ाइलों को तुरंत क्लोन करता है, बजाय इसके कि हर बाइट को अपने ख़ुद के लूप से धकेले।","featuresPage.why.safe.title":"ग़लती से कुछ भी विनाशकारी नहीं","featuresPage.why.safe.body":"मूव मूल फ़ाइल को कॉपी सफल होने के बाद ही हटाता है, पूर्ववत फ़ाइलों को मिटाने के बजाय रीसायकल बिन या ट्रैश में भेजता है, और पूर्ववत उस फ़ाइल को कभी नहीं छूता जो कॉपी होने के बाद बदल चुकी हो।","featuresPage.why.local.title":"यह आपकी मशीन पर ही रहता है","featuresPage.why.local.body":"कोई टेलीमेट्री नहीं और कोई खाता नहीं। आपकी फ़ाइलें केवल वहीं जाती हैं जहाँ आप उन्हें भेजते हैं, और सेटिंग्स फ़ाइल को संपादित करके भी टेलीमेट्री चालू नहीं की जा सकती।","featuresPage.why.noAi.title":"कोई AI नहीं","featuresPage.why.noAi.body":"यह जो कुछ भी तय करता है, वह साधारण, अनुमान लगाने योग्य कोड से आता है: चेकसम, आकार और टाइमस्टैम्प। इसमें कोई मशीन-लर्निंग लाइब्रेरी नहीं है।","featuresPage.limits.heading":"सीमाएँ, साफ़-साफ़","featuresPage.limits.intro":"जो फ़ीचर सूची अपनी कमियाँ छिपाए, वह पढ़ने लायक नहीं। ऊपर का सब कुछ संस्करण 1.0.0 में है, और यह वह है जो यह नहीं करता।","featuresPage.limits.title":"1.0 क्या नहीं करता","featuresPage.limits.verify":"जब तक आप सेटिंग्स → स्थानांतरण में सत्यापन चालू न करें, यह किसी कॉपी को सत्यापित नहीं करता।","featuresPage.limits.queue":"कतार में कार्यों का क्रम नहीं बदला जा सकता: हर कार्य जोड़ते ही शुरू हो जाता है।","featuresPage.limits.portable":"पोर्टेबल मोड सेटिंग्स और प्रोफ़ाइल को ऐप के पास रखता है, लेकिन इतिहास, फिर से शुरू करने का जर्नल और सहेजे गए क्लाउड पासवर्ड उसी कंप्यूटर पर रहते हैं जिस पर यह चलता है।","featuresPage.limits.shred":"यह फ़ाइलों को सुरक्षित रूप से श्रेड नहीं कर सकता: सेटिंग्स → सुरक्षित रूप से हटाना मौजूद है, लेकिन 1.0.0 में कुछ भी उसके ज़रिए नहीं हटाता।","featuresPage.limits.cloud":"यह क्लाउड स्टोरेज पर कॉपी नहीं कर सकता: आप सेटिंग्स → रिमोट्स में क्लाउड खाते जोड़ और जाँच सकते हैं, लेकिन अभी कोई कॉपी उन तक नहीं जाती।","featuresPage.limits.downloads":"इस साइट पर अभी कोई डाउनलोड नहीं है, और इस पेज पर भी नहीं।","docs.intro":"Freally File Manager संस्करण 1.0.0 का उपयोग कैसे करें। बटन, टैब और मेनू यहाँ उन्हीं नामों से बताए गए हैं जो ऐप में दिखते हैं।","docs.start.title":"शुरुआत करना","docs.copy.title":"फ़ाइलें कॉपी करें","docs.move.title":"फ़ाइलें मूव करें","docs.verify.title":"किसी कॉपी को सत्यापित करें","docs.history.title":"इतिहास, दोबारा चलाना और पूर्ववत","docs.checks.title":"हैश, पुनः सत्यापन और चेकसम फ़ाइलें","docs.sync.title":"दो फ़ोल्डर सिंक करें","docs.filters.title":"चुनें कि क्या कॉपी हो","docs.shell.title":"राइट-क्लिक मेनू और पेस्ट शॉर्टकट","docs.library.title":"स्नैपशॉट और बैकअप","docs.salvage.title":"ख़राब होती ड्राइव से फ़ाइल बचाएँ","docs.server.title":"इसे फ़ाइल सर्वर के रूप में चलाएँ","docs.migrate.title":"restic, Borg या Kopia रिपॉज़िटरी लाएँ","docs.settings.title":"सेटिंग्स","docs.shortcuts.title":"कीबोर्ड शॉर्टकट","featuresPage.speed.title":"यह कितना तेज़ है","docs.trouble.title":"सुझाव और समस्या निवारण","docs.report.title":"समस्या की रिपोर्ट करना","docs.privacy.title":"निजता और नेटवर्क","docs.start.p1":"Freally File Manager, Windows 11, macOS 12 या उसके बाद के संस्करण, और Linux के लिए एक डेस्कटॉप ऐप है। पहली बार खुलने पर यह अपना लाइसेंस अनुबंध दिखाता है: अंत तक स्क्रॉल करें, फिर शुरू करने के लिए “मैं सहमत हूँ” चुनें, या “अस्वीकार करें और बाहर निकलें”।","docs.start.p2":"विंडो “गतिविधि” पैनल के ऊपर एक ड्रॉप ज़ोन है। “फ़ाइलें जोड़ें”, “फ़ोल्डर जोड़ें” और “सूची आयात करें” हेडर में हैं। फ़ुटर में “कुल योग”, “इतिहास”, “हैश”, “पुनः सत्यापित करें”, “बचाव”, “सिंक”, “लाइब्रेरी”, “कार्य” और वह गियर है जो “सेटिंग्स” खोलता है।","docs.start.p3":"इस साइट पर अभी कोई डाउनलोड नहीं है।","docs.copy.s1":"फ़ाइलें या फ़ोल्डर विंडो पर खींचें, या हेडर में “फ़ाइलें जोड़ें” या “फ़ोल्डर जोड़ें” पर क्लिक करें।","docs.copy.s2":"“छोड़े गए आइटम स्थानांतरित करें” डायलॉग खुलता है। “ऑपरेशन” को “कॉपी करें” पर ही रहने दें और जिस फ़ोल्डर में कॉपी करना है उसे चुनने के लिए “गंतव्य चुनें” पर क्लिक करें।","docs.copy.s3":"“यदि कोई फ़ाइल पहले से मौजूद है” के नीचे चुनें कि वहाँ पहले से मौजूद फ़ाइलों का क्या हो: दोनों रखें, छोड़ें, ओवरराइट करें, केवल नई होने पर ओवरराइट करें, केवल सामग्री अलग होने पर ओवरराइट करें, एक जैसी होने पर छोड़ें और वरना पूछें, या हर बार पूछें।","docs.copy.s4":"सूची को नाम या आकार के अनुसार क्रमबद्ध करने के लिए “क्रम” का उपयोग करें, या पंक्तियों को खींचें। फ़ाइलें हमेशा फ़ोल्डरों से पहले आती हैं।","docs.copy.s5":"“कॉपी शुरू करें” पर क्लिक करें। हर फ़ाइल को “गतिविधि” पैनल में एक पंक्ति मिलती है, जिसमें उसकी प्रगति, गति और बचा हुआ समय होता है, और हेडर कुल योग दिखाता है।","docs.copy.p1":"किसी कार्य को रोकने के लिए उसकी पंक्ति पर फ़ोकस करके Space दबाएँ, या उस पर राइट-क्लिक करके “रोकें” चुनें; “जारी रखें” उसे आगे बढ़ाता है और “रद्द करें” उसे बंद कर देता है। “सभी कार्य रोकें”, “सभी कार्य जारी रखें” और “सभी कार्य रद्द करें” हेडर में हैं।","docs.copy.p2":"अगर गंतव्य में सब कुछ रखने की जगह नहीं है, तो पहला बाइट हिलने से पहले ही आपको चेतावनी मिलती है और आप चुन सकते हैं कि कौन-से आइटम कॉपी हों। डायलॉग उन नामों को भी चिह्नित करता है जिन्हें गंतव्य नहीं रख सकता, जैसे आरक्षित नाम, अनुमति न दिए गए अक्षर और बहुत लंबे पथ, और उनका नाम बदलने की पेशकश करता है।","docs.copy.p3":"जब सारे कार्य पूरे हो जाएँ, तब ऐप बंद करने, लॉग ऑफ़ करने, शट डाउन करने या स्लीप में जाने के लिए विंडो के नीचे “पूर्ण होने पर” का उपयोग करें।","docs.move.p1":"मूव करना कॉपी करने जैसा ही है: “छोड़े गए आइटम स्थानांतरित करें” डायलॉग में “ऑपरेशन” को “स्थानांतरित करें” पर सेट करें, गंतव्य चुनें और “स्थानांतरण शुरू करें” पर क्लिक करें।","docs.move.p2":"हर फ़ाइल पहले कॉपी होती है, और मूल फ़ाइल कॉपी सफल होने के बाद ही हटाई जाती है। अगर कुछ भी विफल होता है, तो मूल फ़ाइल वहीं रहती है जहाँ थी और पंक्ति विफल के रूप में चिह्नित होती है।","docs.move.p3":"हर मूव को वापस पाने योग्य बनाने के लिए सेटिंग्स → सुरक्षित रूप से हटाना में “मूव किए गए स्रोत फ़ाइलें ट्रैश में भेजें” चालू करें: तब मूल फ़ाइलें हटाए जाने के बजाय रीसायकल बिन या ट्रैश में जाती हैं।","docs.verify.p1":"जब तक आप चालू न करें, सत्यापन बंद रहता है। सेटिंग्स → स्थानांतरण खोलें और “कॉपी के बाद सत्यापित करें” के नीचे एक चेकसम चुनें: xxHash3 सबसे तेज़ है, BLAKE3 मज़बूत होने के साथ तेज़ भी है, और SHA-256 ज़्यादातर दूसरे टूल से मेल खाता है।","docs.verify.p2":"उसके बाद हर कॉपी जाँची जाती है। मूल फ़ाइल का हैश पढ़ते समय ही निकाला जाता है, इसलिए उसे दो बार नहीं पढ़ा जाता; कॉपी लिखे जाने के बाद उसका भी हैश निकाला जाता है और दोनों की तुलना होती है।","docs.verify.p3":"मेल खाने पर पंक्ति पूर्ण के रूप में ख़त्म होती है। बेमेल होने पर पंक्ति विफल होती है और अपेक्षित तथा वास्तविक चेकसम दिखाती है। अगर कोई बड़ी कॉपी 100% पर अटकी लगे, तो शायद हेडर में “सत्यापित हो रहा है” लिखा है: जाँच अभी चल रही है।","docs.history.p1":"फ़ुटर में “इतिहास” पर क्लिक करें। हर कार्य उसके प्रकार, स्रोत, गंतव्य, आकार, स्थिति और अवधि के साथ सूचीबद्ध होता है, और आप सूची को प्रकार, स्थिति या टेक्स्ट से फ़िल्टर कर सकते हैं। “CSV निर्यात करें” इसे सहेजता है।","docs.history.p2":"किसी कार्य पर आप “फिर से चलाएँ” से उसे दोबारा चला सकते हैं, “विफल पुनः प्रयास” से केवल विफल फ़ाइलें कॉपी कर सकते हैं, “विफल निर्यात करें” से वह सूची सहेज सकते हैं, “पुनः सत्यापित करें” से उसे दोबारा जाँच सकते हैं, या “प्रमाणपत्र” निर्यात कर सकते हैं: हर फ़ाइल के चेकसम, आकार और स्थिति की प्रिंट करने योग्य HTML, CSV या JSON रिपोर्ट, जिस पर आप अपनी कुंजी से हस्ताक्षर कर सकते हैं।","docs.history.p3":"“पूर्ववत करें”, या Ctrl+Z, ठीक-ठीक यह दिखाने के बाद कि वह किन चीज़ों को छुएगा, सबसे नई कॉपी या मूव को उलट देता है। कॉपी की गई फ़ाइलें रीसायकल बिन या ट्रैश में जाती हैं, और केवल तभी जब वे अब भी कॉपी की गई सामग्री से मेल खाती हों; मूव की गई फ़ाइलें वहीं लौट जाती हैं जहाँ से आई थीं।","docs.history.p4":"“कुल योग”, जो फ़ुटर में ही है, बाइट, फ़ाइलों और कार्यों के अब तक के कुल आँकड़े और पिछले 30 दिनों का एक चार्ट दिखाता है।","docs.checks.p1":"फ़ुटर में “हैश” हैश निरीक्षक खोलता है। फ़ाइलें या फ़ोल्डर जोड़ें, एक एल्गोरिदम चुनें और “हैश निकालें” पर क्लिक करें। तुलना के लिए कोई चेकसम, किसी चेकसम फ़ाइल की कोई पंक्ति या SFV की कोई पंक्ति पेस्ट करें, या यह देखने के लिए दो फ़ाइलें चुनें कि वे एक जैसी हैं या नहीं।","docs.checks.p2":"“पुनः सत्यापित करें”, जो फ़ुटर में ही है, किसी फ़ोल्डर की उसकी कॉपी से फिर से तुलना करता है, कभी भी और कुछ भी लिखे बिना। यह हर उस फ़ाइल की रिपोर्ट देता है जो मेल खाती है, अलग है, कॉपी में नहीं है, केवल कॉपी में है, या पढ़ी नहीं जा सकती।","docs.checks.p3":"पूरे फ़ोल्डर के लिए चेकसम फ़ाइल बनाने के लिए किसी पूरे हो चुके कार्य पर राइट-क्लिक करें और “चेकसम बनाएँ (SHA-256)” चुनें। किसी को जाँचने के लिए विंडो पर एक .md5, .sha1, .sha256, .sha512, .b3 या .sfv फ़ाइल छोड़ें: उसमें सूचीबद्ध हर फ़ाइल का हैश निकाला जाता है और नतीजा दिखाया जाता है।","docs.sync.s1":"फ़ुटर में “सिंक” पर क्लिक करें, फिर “जोड़ी जोड़ें” पर।","docs.sync.s2":"जोड़ी को एक लेबल दें, बायाँ और दायाँ फ़ोल्डर चुनें, और एक मोड चुनें: “दोतरफ़ा”; “मिरर”, बाएँ से दाएँ या दाएँ से बाएँ; या “योगदान”, जो बाएँ से दाएँ कॉपी करता है और कभी कुछ नहीं हटाता।","docs.sync.s3":"“जोड़ी सहेजें” पर क्लिक करें, फिर “अभी चलाएँ” पर।","docs.sync.p1":"जब पिछली बार चलने के बाद कोई फ़ाइल दोनों तरफ़ बदल चुकी हो, तो कुछ भी ओवरराइट नहीं होता: दूसरा संस्करण उसके बगल में सिंक-टकराव फ़ाइल के रूप में रखा जाता है, और “टकराव देखें” से आप बायाँ, दायाँ या दोनों रख सकते हैं।","docs.sync.p2":"“लाइव मिरर शुरू करें” बाएँ फ़ोल्डर पर नज़र रखता है और आपके सहेजे हर बदलाव के बाद फिर से सिंक करता है। चलते समय जोड़ी “नज़र रखी जा रही है” दिखाती है; “लाइव मिरर रोकें” इसे ख़त्म करता है।","docs.filters.p1":"सेटिंग्स → फ़िल्टर हर कॉपी पर लागू होता है: शामिल करने या बाहर रखने के पैटर्न, जैसे **/*.log या **/node_modules, आकार और तारीख़ की सीमाएँ, और यह कि छिपी, सिस्टम या केवल-पढ़ने योग्य फ़ाइलें छोड़ी जाएँ या नहीं। बाहर रखने के किसी पैटर्न से मेल खाने वाला फ़ोल्डर पूरा का पूरा छोड़ दिया जाता है।","docs.filters.p2":"फ़ाइलों की एक सटीक सूची कॉपी करने के लिए हेडर में “सूची आयात करें” पर क्लिक करें और पथों वाली एक TXT, CSV या JSON फ़ाइल चुनें। उन्हें सपाट रूप से एक फ़ोल्डर में कॉपी करें, या उनके फ़ोल्डरों को एक साझा रूट के नीचे बनाए रखें।","docs.filters.p3":"किसी बड़ी कॉपी से पहले, “छोड़े गए आइटम स्थानांतरित करें” डायलॉग में “योजना निर्यात करें” एक रिपोर्ट सहेजता है कि कॉपी क्या जोड़ेगी, क्या बदलेगी, क्या छोड़ेगी या किसमें टकराव पाएगी, एक भी बाइट हिलने से पहले।","docs.shell.p1":"Freally File Manager राइट-क्लिक मेनू में “Copy with Freally File Manager” और “Move with Freally File Manager” जोड़ सकता है: Windows पर Explorer में, macOS पर Finder में, और Linux पर Nautilus, Dolphin और Thunar में। Windows पर सेटिंग्स → शेल इन्हें चालू या बंद करता है।","docs.shell.p2":"फ़ाइलों को हमेशा की तरह Ctrl+C (Mac पर Cmd+C) से कॉपी करें, फिर कहीं भी Ctrl+Shift+V (Mac पर Cmd+Shift+V) दबाएँ: फ़ाइलें Freally File Manager के डायलॉग में खुल जाती हैं। शॉर्टकट बदलें या उसे सेटिंग्स → सामान्य में बंद करें।","docs.shell.p3":"Windows पर आप और आगे जा सकते हैं: सेटिंग्स → शेल में “डिफ़ॉल्ट कॉपी हैंडलर इंटरसेप्ट करें” Explorer के अपने कॉपी और पेस्ट को Freally File Manager के ज़रिए भेजता है, और फिर हर पेस्ट पूछता है कि आप साधारण सिस्टम कॉपी चाहते हैं या सत्यापित कॉपी। “Windows कॉपी हैंडलर पर वापस लौटें” इसे एक क्लिक में पलट देता है।","docs.library.p1":"फ़ुटर में “लाइब्रेरी” रिपॉज़िटरी खोलती है: हर फ़ाइल की सामग्री डिडुप्लिकेट किए गए टुकड़ों में एक ही बार संग्रहित होती है, और हर स्नैपशॉट एक ही टाइमलाइन पर दिखाया जाता है। हेडर दिखाता है कि डिस्क पर कितना संग्रहित है और वह कितने का प्रतिनिधित्व करता है।","docs.library.p2":"“स्रोत” पर एक फ़ोल्डर जोड़ें और स्नैपशॉट लेने के लिए “अभी बैकअप लें” पर क्लिक करें; बिना बदले फ़ोल्डर का दूसरा बैकअप लगभग कोई जगह नहीं लेता। हर स्रोत अपने सभी स्नैपशॉट, आख़िरी कुछ, या एक घूमता हुआ सेट रख सकता है, और हर घंटे, रोज़ या हर हफ़्ते चल सकता है।","docs.library.p3":"“स्नैपशॉट” पर, “पुनर्स्थापित करें” से आप किसी स्नैपशॉट की फ़ाइलें ब्राउज़ कर सकते हैं, गंतव्य चुन सकते हैं और तय कर सकते हैं कि पहले से मौजूद फ़ाइलों का क्या हो। “भूल जाएँ” एक स्नैपशॉट हटा देता है, और “स्थान पुनः प्राप्त करें” उन टुकड़ों को मुक्त करता है जिनका अब कोई उपयोग नहीं करता।","docs.salvage.p1":"फ़ुटर में “बचाव” क्षतिग्रस्त ड्राइव पर किसी फ़ाइल का जितना हिस्सा अब भी पढ़ा जा सकता है, उसे कॉपी करता है। फ़ाइल चुनें, फिर यह कि कॉपी कहाँ लिखी जाए।","docs.salvage.p2":"न पढ़े जा सकने वाले हिस्सों का छोटे से छोटे टुकड़ों में पुनः प्रयास होता है, फिर उन्हें शून्यों से भर दिया जाता है ताकि फ़ाइल का बाक़ी हिस्सा अपनी जगह पर रहे, और अंतरालों का एक नक्शा कॉपी के बगल में सहेजा जाता है। बाद में उसी फ़ाइल पर फिर से “बचाव” चलाएँ, तो केवल अंतरालों को आज़माया जाता है।","docs.salvage.p3":"अंतरालों वाली बचाई गई फ़ाइल बाइट-दर-बाइट सटीक कॉपी नहीं है, और उसकी इतिहास प्रविष्टि यह बताती है।","docs.server.p1":"Freally File Manager किसी फ़ोल्डर को दूसरे कंप्यूटरों के लिए WebDAV, सादे HTTP, S3-संगत API या SFTP पर सर्व कर सकता है।","docs.server.s1":"सेटिंग्स → सर्वर खोलें और जिन प्रोटोकॉल की पेशकश करनी है उन पर टिक करें।","docs.server.s2":"बाइंड पता सेट करें। डिफ़ॉल्ट 127.0.0.1:8080 केवल इसी कंप्यूटर को सर्व करता है; 0.0.0.0:8080 या आपका नेटवर्क पता दूसरों को सर्व करता है, जब आपका फ़ायरवॉल इसकी अनुमति दे।","docs.server.s3":"सर्व किया जाने वाला फ़ोल्डर चुनें, अगर कुछ भी अपलोड या हटाया नहीं जाना चाहिए तो “केवल पढ़ने योग्य” पर टिक करें, और प्रमाणीकरण चुनें: कोई नहीं, बेयरर टोकन, या उपयोगकर्ता नाम और पासवर्ड।","docs.server.s4":"“सर्वर शुरू करें” पर क्लिक करें। स्थिति पंक्ति पता दिखाती है, और एक “मेट्रिक्स” लिंक Prometheus एंडपॉइंट की ओर ले जाता है। “सर्वर रोकें”, या ऐप से बाहर निकलना, इसे रोक देता है।","docs.server.protocol":"प्रोटोकॉल","docs.server.connect":"किससे कनेक्ट करें","docs.server.webdav":"Windows में “नेटवर्क ड्राइव मैप करें”, Finder में “सर्वर से कनेक्ट करें”, GNOME Files या davfs2","docs.server.http":"कोई वेब ब्राउज़र, curl या wget","docs.server.s3client":"AWS कमांड लाइन, rclone या कोई भी S3 लाइब्रेरी, जिसमें उपयोगकर्ता नाम और पासवर्ड को एक्सेस कुंजी और सीक्रेट के रूप में डाला जाए","docs.server.sftp":"sftp, scp, FileZilla, WinSCP या rclone","docs.server.p2":"WebDAV और HTTP एक ही पते पर साथ-साथ चल सकते हैं; S3 और SFTP को अपना-अपना अलग सर्वर चाहिए, और S3 को टोकन के बजाय पासवर्ड चाहिए या कोई प्रमाणीकरण नहीं।","docs.server.p3":"बिना प्रमाणीकरण के नेटवर्क के लिए खुले सर्वर को, उस तक पहुँच सकने वाली कोई भी चीज़ पढ़ सकती है, और अगर वह केवल पढ़ने योग्य न हो तो उस पर लिख भी सकती है। अपने कंप्यूटर से बाहर के लिए हमेशा टोकन या पासवर्ड सेट करें।","docs.server.p4":"बिना स्क्रीन वाले कंप्यूटर पर freally कमांड यही काम करता है:","docs.migrate.p1":"freally migrate कमांड किसी दूसरे बैकअप टूल की रिपॉज़िटरी पढ़ता है, हर फ़ाइल को फिर से बनाता है और उसे खुले CDR-0 फ़ॉर्मैट की एक रिपॉज़िटरी में संग्रहित करता है, Freally File Manager की अपनी चंकिंग से फिर से डिडुप्लिकेट करके।","docs.migrate.p2":"हर इम्पोर्टर को इस बात के लिए परखा गया है कि वह हर फ़ाइल को बाइट-दर-बाइट पुनर्स्थापित करे। CDR-0 फ़ॉर्मैट का वर्णन इस साइट के साथ प्रकाशित विनिर्देश में है।","docs.migrate.spec":"CDR-0 विनिर्देश पढ़ें","docs.settings.p1":"फ़ुटर में गियर “सेटिंग्स” खोलता है। बदलाव तुरंत लागू होते हैं, बिना रीस्टार्ट के। जिन टैब का आप सबसे ज़्यादा उपयोग करेंगे:","docs.settings.general":"सामान्य: भाषा, ऐप की थीम, लॉगिन पर शुरू होना, ट्रे में मिनिमाइज़ करना, त्रुटियाँ कैसे दिखें, पेस्ट शॉर्टकट और क्लिपबोर्ड पर नज़र।","docs.settings.transfer":"स्थानांतरण: सत्यापन, बफ़र आकार, एक साथ कितनी फ़ाइलें कॉपी हों, क्लोन, टाइमस्टैम्प और अनुमतियाँ, स्पार्स फ़ाइलें, लॉक की गई फ़ाइलें और फ़ाइल पर लगे सुरक्षा निशान।","docs.settings.filters":"फ़िल्टर: क्या शामिल करना है और क्या बाहर रखना है।","docs.settings.shell":"शेल: राइट-क्लिक मेनू और Windows की अपनी कॉपी को अपने हाथ में लेना।","docs.settings.network":"नेटवर्क: गति सीमा, स्थिर या किसी शेड्यूल पर।","docs.settings.server":"सर्वर: बिल्ट-इन फ़ाइल सर्वर।","docs.settings.updates":"अपडेट: रोज़ाना की अपडेट जाँच, और अभी जाँचने के लिए एक बटन।","docs.settings.profiles":"प्रोफ़ाइल: अपनी सेटिंग्स को किसी नाम से सहेजें, उनके बीच बदलें, और उन्हें आयात या निर्यात करें।","docs.shortcuts.keys":"कुंजियाँ","docs.shortcuts.action":"यह क्या करता है","docs.shortcuts.paste":"कॉपी की गई फ़ाइलें कहीं से भी Freally File Manager के ज़रिए पेस्ट करें","docs.shortcuts.undo":"सबसे नई कॉपी या मूव को पूर्ववत करें","docs.shortcuts.pause":"फ़ोकस किए गए कार्य को रोकें या जारी रखें","docs.shortcuts.escape":"सबसे ऊपर का डायलॉग या ड्रॉअर बंद करें","featuresPage.speed.intro":"30 अप्रैल 2026 को एक Windows 11 लैपटॉप (Intel Core i9-13900HX, 32 GB मेमोरी, एक PCIe 4.0 NVMe ड्राइव) पर मापा गया, एक ही NTFS ड्राइव के भीतर कॉपी करते हुए। हर आँकड़ा कई रन का माध्यिका (median) मान है, MiB प्रति सेकंड में: ज़्यादा यानी तेज़।","featuresPage.speed.workload":"क्या कॉपी किया गया","featuresPage.speed.cmd":"Windows की copy कमांड","featuresPage.speed.mixed":"100 फ़ाइलों का एक फ़ोल्डर, 100 KB से 150 MB तक","featuresPage.speed.file512":"512 MB की एक फ़ाइल","featuresPage.speed.file256":"256 MB की एक फ़ाइल","featuresPage.speed.file10g":"10 GB की एक फ़ाइल","featuresPage.speed.result":"फ़ाइलों वाले फ़ोल्डर और 512 MB फ़ाइल पर यह सबसे तेज़ रहा, और 256 MB तथा 10 GB फ़ाइलों पर Robocopy और Windows की copy कमांड से थोड़ा धीमा रहा। हर परीक्षण में यह FastCopy और TeraCopy से तेज़ रहा।","featuresPage.speed.caveat":"एक मशीन और एक ड्राइव, 1.0.0 से पहले के एक बिल्ड से मापा गया, और हर टूल अपनी ही कमांड लाइन से चलाया गया, शुरू होने का समय भी शामिल करके। आपके आँकड़े अलग होंगे, और जब गंतव्य ड्राइव सबसे धीमा हिस्सा हो, तो हर टूल उसी की गति से चलता है।","docs.trouble.slow.title":"मेरी कॉपी धीमी क्यों है?","docs.trouble.slow.body":"जब कोई कॉपी अपनी अपेक्षित गति से धीमी चलती है, तो हेडर एक छोटा बैज दिखाता है जो कारण बताता है: स्रोत डिस्क, गंतव्य डिस्क, नेटवर्क, एंटीवायरस स्कैनर, प्रोसेसर या गर्मी। विवरण के लिए उस पर माउस ले जाएँ।","docs.trouble.stall.title":"कॉपी 100% पर रुक जाती है","docs.trouble.stall.body":"अगर हेडर में “सत्यापित हो रहा है” लिखा है, तो कॉपी को उसके चेकसम से जाँचा जा रहा है। बड़ी फ़ाइलों के लिए यह सामान्य है; अगर आपको इसकी ज़रूरत नहीं है तो सेटिंग्स → स्थानांतरण में सत्यापन बंद कर दें।","docs.trouble.locked.title":"Windows पर कोई फ़ाइल उपयोग में है","docs.trouble.locked.body":"फ़ाइलें इस तरह खोली जाती हैं कि दूसरे प्रोग्राम उनका उपयोग करते रह सकें, और अस्वीकार की गई फ़ाइल का कुछ बार पुनः प्रयास होता है। अगर कोई दूसरा प्रोग्राम फिर भी उसे विशेष रूप से पकड़े रखे, तो उस प्रोग्राम को बंद करें, या सेटिंग्स → स्थानांतरण में लॉक की गई फ़ाइलों को स्नैपशॉट से कॉपी करना चुनें।","docs.trouble.permission.title":"अनुमति अस्वीकृत","docs.trouble.permission.body":"जब अनुमतियों के कारण फ़ाइलें अस्वीकार हो जाती हैं, तो Freally File Manager पूरी सूची के लिए एक ही एडमिनिस्ट्रेटर प्रॉम्प्ट से उनका पुनः प्रयास कर सकता है, और आपके मंज़ूरी देने से पहले ठीक-ठीक दिखाता है कि वह किन फ़ाइलों को छुएगा।","docs.trouble.changed.title":"कॉपी के दौरान स्रोत बदल गया","docs.trouble.changed.body":"फ़ाइल पढ़े जाते समय बदल गई, इसलिए कॉपी में पुरानी और नई सामग्री मिली हुई हो सकती है। डिफ़ॉल्ट रूप से फ़ाइल चिह्नित की जाती है; इसके बजाय सेटिंग्स → स्थानांतरण उसे एक बार फिर से कॉपी कर सकता है या विफल कर सकता है।","docs.report.p1":"जब ऐप ख़ुद कोई त्रुटि पैदा करता है, तो संदेश के बगल में एक “रिपोर्ट करें” बटन दिखता है। क्रैश के बाद, अगली बार ऐप खुलने पर “रिपोर्ट करें” या “ख़ारिज करें” का विकल्प मिलता है।","docs.report.p2":"“रिपोर्ट करें” इस पेज को आपके ब्राउज़र में खोलता है, जिसमें तकनीकी जानकारी पहले से भरी होती है: आप उसे पढ़ सकते हैं लेकिन बदल नहीं सकते। लिखें कि आप क्या कर रहे थे और, चाहें तो, जवाब के लिए एक ईमेल पता।","docs.report.p3":"जब तक आप उस पेज पर “भेजें” नहीं दबाते, कुछ नहीं भेजा जाता, और पृष्ठभूमि में कभी कुछ नहीं भेजा जाता। रिपोर्ट में फ़ाइल पथ छोटे कर दिए जाते हैं, और आपका होम फ़ोल्डर ~ के रूप में दिखता है।","docs.privacy.p1":"Freally File Manager में कोई खाता नहीं है और कोई टेलीमेट्री नहीं है। इसकी सेटिंग्स में टेलीमेट्री स्विच हमेशा के लिए बंद है: सेटिंग्स फ़ाइल में हाथ से लिखा गया मान अनदेखा कर दिया जाता है।","docs.privacy.p2":"आपकी अपनी ड्राइव पर फ़ाइलें कॉपी करना, मूव करना और सत्यापित करना कोई नेटवर्क अनुरोध नहीं करते। ऐप उन चीज़ों के लिए ऑनलाइन जाता है जिन्हें आप सेट करते हैं, जैसे फ़ाइल सर्वर या किसी क्लाउड खाते की जाँच, और शुरू होने पर अपडेट जाँचने के लिए, दिन में अधिकतम एक बार। अपडेट जाँच केवल रिलीज़ की सूची पढ़ती है, आपकी कोई फ़ाइल या पथ नहीं भेजती, और सेटिंग्स → अपडेट में बंद की जा सकती है।","docs.privacy.p3":"इसमें कोई AI नहीं है: यह जो कुछ भी तय करता है वह चेकसम, आकार और टाइमस्टैम्प से आता है, और कोई मशीन-लर्निंग लाइब्रेरी इसका हिस्सा नहीं है।","kit.skip":"सामग्री पर जाएँ","kit.nav.site":"साइट","kit.nav.home":"होम","kit.nav.features":"फ़ीचर्स","kit.nav.documentation":"दस्तावेज़ीकरण","kit.nav.changelog":"बदलाव लॉग","kit.nav.language":"भाषा","kit.nav.allApps":"सभी Freally ऐप्स","kit.badge.done":"v1.0.0 पूरा","kit.cta.features":"सभी फ़ीचर्स देखें","kit.cta.docs":"दस्तावेज़ीकरण पढ़ें","kit.price":"Freally File Manager आज मुफ़्त है, लेकिन हो सकता है कि यह हमेशा मुफ़्त न रहे: भविष्य के संस्करण बेचे जा सकते हैं।","kit.noDownloads":"अभी कोई डाउनलोड नहीं है, और सोर्स कोड निजी है।","kit.label.overview":"अवलोकन","kit.label.inside":"अंदर","kit.label.roadmap":"रोडमैप","kit.ladder.done":"पूरा","kit.label.honesty":"ईमानदारी","kit.family.label":"Freally परिवार","kit.family.title":"<span class=\"hl-muted\">एक परिवार।</span> <span class=\"hl-bright\">आठ ऐप्स।</span>","kit.cta.label":"क्या बदला","kit.cta.title":"<span class=\"hl-muted\">हर संस्करण,</span> <span class=\"hl-bright\">लिखित में।</span>","kit.cta.lede":"बदलाव लॉग में Freally File Manager में हुआ हर बदलाव, संस्करण-दर-संस्करण, सभी अठारह भाषाओं में दर्ज है।","kit.cta.changelog":"बदलाव लॉग पढ़ें","kit.footer.thisApp":"यह ऐप","kit.footer.family":"Freally परिवार","kit.status.devVersion":"विकास में · v1.0.0","kit.head.features":"<span class=\"hl-muted\">यह जो कुछ करता है,</span> <span class=\"hl-bright\">आमने-सामने।</span>","kit.label.numbers":"आँकड़ों में","kit.label.free":"आज मुफ़्त","kit.label.compare":"तुलना","kit.label.principles":"सिद्धांत","kit.label.limits":"सीमाएँ","kit.states.title":"स्थितियों का अर्थ","kit.states.done":"बना और टैग किया गया, पर इस साइट पर डाउनलोड नहीं","kit.states.ladder":"रास्ते का हर पड़ाव देखें","kit.head.documentation":"<span class=\"hl-muted\">यह कैसे काम करता है,</span> <span class=\"hl-bright\">क़दम-दर-क़दम।</span>","kit.search.placeholder":"दस्तावेज़ीकरण में खोजें","kit.docs.contents":"विषय-सूची","kit.head.changelog":"<span class=\"hl-muted\">हर बदलाव,</span> <span class=\"hl-bright\">संस्करण-दर-संस्करण।</span>","kit.changelog.lede":"सबसे नया पहले: Freally File Manager में जो कुछ बदला, इस साइट की हर भाषा में।","kit.changelog.versions":"संस्करण","kit.search.none":"इस साइट पर इससे कुछ भी मेल नहीं खाता।","kit.zoom.close":"बंद करें","changelog.086fc6b9eb45":"<span class=\"release__meta\"><span class=\"release__ver\">v1.0.0</span><time class=\"release__date\" datetime=\"2026-08-22\">2026-08-22</time></span><span class=\"release__title\">शुद्धता वाली रिलीज़</span>","changelog.490081990d07":"0.22.0 की हर सुविधा यहाँ मौजूद है। जो बदला, वह है कोड की खंड-दर-खंड पूरी समीक्षा, और उससे निकले सुधार। इनमें से कई ख़ामियाँ कभी कोई त्रुटि दिखाए बिना डेटा खो सकती थीं।","changelog.1246fc93bca0":"ठीक किया गया","changelog.f485232d66fe":"<strong>शॉर्टकट फ़ोल्डर।</strong> ऐसा फ़ोल्डर कॉपी करना जो ख़ुद एक शॉर्टकट हो (सिंबॉलिक लिंक या जंक्शन) कुछ भी कॉपी नहीं करता था और सफलता बताता था, और सिंक में यही ख़ामी दूसरी तरफ़ को ख़ाली कर सकती थी। अब ऐसा फ़ोल्डर कारण बताकर अस्वीकार कर दिया जाता है।","changelog.b5ca80d81af1":"<strong>रद्द करना।</strong> किसी बड़े फ़ोल्डर की कॉपी रद्द करने पर वह रुकने के बजाय अटक सकती थी। अब कॉपी को किसी भी समय रद्द किया जा सकता है।","changelog.02ca0292cb02":"<strong>S3 सर्वर।</strong> AWS कमांड लाइन या किसी AWS लाइब्रेरी से अपलोड की गई फ़ाइलें क्षतिग्रस्त होकर संग्रहित होती थीं, और लगभग 8 MB से बड़े अपलोड सीधे विफल हो जाते थे। अब दोनों बाइट-दर-बाइट पहुँचते हैं, और बीच में कटा अपलोड संग्रहित होने के बजाय अस्वीकार कर दिया जाता है।","changelog.00349386830d":"<strong>सिंक डेटाबेस।</strong> जिस सिंक जोड़ी का डेटाबेस उसके अपने ही किसी फ़ोल्डर के अंदर था, वह उस डेटाबेस को सिंक की जाने वाली फ़ाइल मानती थी, और रन के बीच में उसे हटा सकती थी।","changelog.f1d849633a99":"<strong>SFTP।</strong> SFTP रिमोट कभी कनेक्ट नहीं होते थे: हर कनेक्शन जाँच विफल हो जाती थी, सेटिंग्स चाहे जो हों। अब वे कनेक्ट होते हैं।","changelog.fd3bac863255":"<strong>एन्क्रिप्शन।</strong> जब एन्क्रिप्शन की कुंजी तैयार नहीं हो पाती थी, तो वह सादी फ़ाइलें लिखने पर लौट सकता था। अब वह इसके बजाय कार्य रोक देता है।","changelog.94d9edfe63bf":"<strong>केवल-पढ़ने योग्य सर्वर।</strong> एक तरह का अनुरोध अब भी केवल पढ़ने के लिए सेट सर्वर पर लिख सकता था। अब कोई भी नहीं लिख सकता।","changelog.44b306c0f111":"<strong>प्रगति।</strong> फिर से शुरू किया गया स्कैन फ़ाइलों की ग़लत संख्या बताता था, इसलिए प्रगति बार दोनों दिशाओं में ग़लत होते थे।","changelog.e19d94517f4b":"<strong>क्लाउड साइन-इन।</strong> किसी क्लाउड खाते में साइन इन बिना किसी दिखने वाले कारण के विफल हो सकता था, और साइन-इन बीच में छोड़ने पर हर बार एक थ्रेड लीक होता था।","changelog.b4dfc2b6c682":"<strong>ज्ञात होस्ट।</strong> <code>known_hosts</code> फ़ाइल में पिन किया गया SFTP सर्वर तब-तब अस्वीकार हो जाता था जब वह सूची में सबसे पहले दिए गए प्रकार के अलावा कोई भी कुंजी प्रकार पेश करता था, जो ज़्यादातर समय होता है।","changelog.042c3c3e6ae5":"<strong>सूचनाएँ।</strong> ntfy सूचनाएँ संदेश के बजाय कच्चे कोड के रूप में आती थीं।","changelog.6e72325e73e3":"<strong>डायलॉग।</strong> दो डायलॉग खुले होने पर Escape ग़लत डायलॉग बंद कर देता था, और सेटिंग्स के कुछ पैनल ग़लत ढंग से व्यवस्थित थे।","changelog.acdd2a3d27ea":"<strong>एडमिनिस्ट्रेटर प्रॉम्प्ट (सुरक्षा)।</strong> Linux और macOS पर, आपके नाम से चल रहा कोई दूसरा प्रोग्राम पासवर्ड प्रॉम्प्ट खुले रहने के दौरान अपना कनेक्शन बीच में डाल सकता था, और आपकी मंज़ूरी के बाद एडमिनिस्ट्रेटर के रूप में चलने वाला वही बन सकता था। अब प्रॉम्प्ट पर इस तरह क़ब्ज़ा नहीं किया जा सकता।","changelog.577866d56150":"<strong>बड़े अक्षर।</strong> Windows और macOS पर <code>Photo.jpg</code> और <code>photo.jpg</code> एक ही फ़ाइल हैं, लेकिन सिंक उन्हें दो मानता था, हर एक को दूसरे के ऊपर कॉपी करता था, और फिर बची हुई फ़ाइल को हटा सकता था। अब वे फिर से एक ही फ़ाइल हैं।","changelog.f029d4f5e78c":"<strong>नेटवर्क ड्राइव।</strong> नेटवर्क ड्राइव पर रखे फ़ोल्डर को सर्व करते समय अब एक धीमा जवाब बाक़ी सभी अनुरोधों को नहीं रोक पाता।","changelog.0ab356a87732":"<strong>हेल्पर।</strong> इंस्टॉलरों में वह छोटा हेल्पर छूट गया था जो एडमिनिस्ट्रेटर अधिकारों वाला हर काम करता है, इसलिए इंस्टॉल की गई कॉपी पर वे काम विफल हो जाते थे, जैसे अनुमतियों के कारण अस्वीकार हुई कॉपी का पुनः प्रयास या राइट-क्लिक मेनू बदलना। अब हेल्पर ऐप के साथ ही आता है।","changelog.87a38eb16185":"<strong>अपडेट की जाँच।</strong> यह हर बार, हर सिस्टम पर विफल होती थी। अब यह हर रिलीज़ के साथ प्रकाशित अपडेट की सूची पढ़ती है।","changelog.7a7604d1c245":"<strong>रिलीज़ नोट्स।</strong> “अपडेट” पैनल बदलाव लॉग का लिंक चार बार दोहराता था और उसे बेजान टेक्स्ट की तरह दिखाता था। अब नोट्स एक बार दिखते हैं, ऐसे लिंक के साथ जो आपके ब्राउज़र में खुलता है।","changelog.9b82b2eda918":"ऐसे व्यवहार का वादा करने वाला <strong>दस्तावेज़ीकरण</strong>, जो कोड में था ही नहीं, ठीक कर दिया गया।","changelog.d04ef101813e":"<span class=\"release__meta\"><span class=\"release__ver\">v0.22.0</span><time class=\"release__date\" datetime=\"2026-08-19\">2026-08-19</time></span><span class=\"release__title\">हैशिंग, रिपोर्ट, शेड्यूलिंग और पोर्टेबिलिटी</span>","changelog.6b02e0d363a4":"जोड़ा गया","changelog.68724824e3df":"<strong>हैश निरीक्षक।</strong> किसी भी फ़ाइल या फ़ोल्डर का हैश आठ में से किसी भी एल्गोरिदम से निकालें, तुलना के लिए कोई चेकसम पेस्ट करें, या दो फ़ाइलों की तुलना करें। Windows पर यह राइट-क्लिक मेनू में भी है।","changelog.c3b19859a18b":"<strong>कॉपी रिपोर्ट।</strong> किसी भी पूरे हो चुके कार्य को प्रिंट करने योग्य HTML रिपोर्ट, CSV या JSON के रूप में निर्यात करें, जिसमें हर फ़ाइल का चेकसम, आकार और स्थिति हो, और चाहें तो उस पर अपनी कुंजी से हस्ताक्षर करें, ताकि कोई भी उसे Freally File Manager के बिना जाँच सके।","changelog.19be8c01d283":"<strong>पुनः सत्यापन।</strong> महीनों बाद किसी फ़ोल्डर की उसकी कॉपी से फिर से तुलना करें, एक भी बाइट लिखे बिना: क्या मेल खाता है, क्या अलग है, क्या ग़ायब है और क्या जोड़ा गया।","changelog.66e001519d0e":"<strong>फ़ाइल-नाम डॉक्टर।</strong> कॉपी से पहले वे नाम खोजें जिन्हें गंतव्य नहीं रख सकता, जैसे आरक्षित नाम, अनुमति न दिए गए अक्षर, अंत में बिंदु और स्पेस, बहुत लंबे पथ और ऐसे नाम जो केवल बड़े-छोटे अक्षरों में अलग हैं, और उनका नाम बदलें।","changelog.497980a00899":"<strong>सूची से कॉपी।</strong> किसी TXT, CSV या JSON फ़ाइल से पथों की सूची को कॉपी की जाने वाली फ़ाइलों के रूप में आयात करें, सपाट रूप में या उनके फ़ोल्डर बनाए रखते हुए।","changelog.e70e0cbe1516":"<strong>योजना रिपोर्ट।</strong> निर्यात करें कि कोई कॉपी क्या जोड़ेगी, क्या बदलेगी, क्या छोड़ेगी या किसमें टकराव पाएगी, एक भी बाइट हिलने से पहले।","changelog.650a70fbc1fb":"<strong>बचाव।</strong> ख़राब होती ड्राइव पर किसी फ़ाइल का जितना हिस्सा अब भी पढ़ा जा सकता है उसे कॉपी करें, न पढ़े जा सकने वाले हिस्सों को शून्यों से भरें, अंतरालों का नक्शा रखें, और बाद में केवल अंतरालों का पुनः प्रयास करें।","changelog.098ec7cfa416":"<strong>कई फ़ाइलों के लिए एक प्रॉम्प्ट।</strong> जब कई फ़ाइलें अनुमतियों के कारण अस्वीकार हुई हों, तो एक सूची को मंज़ूरी दें और एक ही एडमिनिस्ट्रेटर प्रॉम्प्ट से सबका पुनः प्रयास करें।","changelog.f231630df24f":"<strong>शेड्यूल।</strong> अपने सिस्टम के अपने शेड्यूलर (टास्क शेड्यूलर, launchd या systemd) में प्रविष्टियाँ बनाएँ, संपादित करें और हटाएँ, अगले रन का समय देखते हुए और बिना एडमिनिस्ट्रेटर अधिकारों के।","changelog.9d433f36b4af":"<strong>ड्राइव कतारें।</strong> ग़लत होने पर ड्राइव की पहचान को सुधारें: फ़ोल्डरों को एक साझा कतार में रखें, या उन्हें अलग करें, हर एक के लिए वर्करों की संख्या के साथ।","changelog.1be51474008d":"<strong>प्राथमिकता दें।</strong> एक कार्य पूरा होने तक बाक़ी चल रहे कार्यों को रोकें, फिर ठीक उन्हीं को फिर से जारी करें।","changelog.60c6175a344d":"<strong>पसंदीदा।</strong> स्रोतों, गंतव्यों और स्रोत-से-गंतव्य जोड़ियों को बुकमार्क करें, और हाल की किसी जोड़ी को एक क्लिक में पसंदीदा बना लें।","changelog.332cc7aa8523":"<strong>पोर्टेबल मोड।</strong> <code>--portable</code>, या ऐप के बगल में रखी एक मार्कर फ़ाइल, सेटिंग्स और प्रोफ़ाइल को ऐप के पास ही रखती है। इतिहास, फिर से शुरू करने का जर्नल और सहेजे गए क्लाउड पासवर्ड फिर भी कंप्यूटर पर ही रहते हैं, और सेटिंग्स यह बताती हैं।","changelog.2eb9e1222a1d":"<strong>सुलभता।</strong> Escape कहीं से भी सबसे ऊपर का डायलॉग बंद करता है, कम मोशन की पसंद का हर जगह सम्मान होता है, फ़ोकस हमेशा दिखता है, और स्क्रीन रीडर चल रहे, पूरे हुए और विफल कार्यों की गिनती सुनता है।","changelog.3c3c4afca24f":"<strong>स्रोत-स्थिरता सुरक्षा।</strong> कॉपी होते समय बदलने वाली फ़ाइल को, आपकी पसंद के अनुसार, चिह्नित किया जाता है, एक बार फिर से कॉपी किया जाता है या विफल किया जाता है।","changelog.1d54a1bf0dc3":"<strong>लॉगिन पर शुरू करें।</strong> ट्रे में मिनिमाइज़ होकर शुरू करें, ताकि राइट-क्लिक मेनू, पेस्ट शॉर्टकट और शेड्यूल आपके साइन इन करते ही काम करें।","changelog.8dbeb02b73fb":"<strong>सेटिंग्स आपका डेटा मिटा सकती थीं।</strong> सेटिंग्स सहेजने पर ट्रे में पिन किए गंतव्य, रिपॉज़िटरी, क्लाउड खाते, सिंक जोड़ियाँ और बहुत कुछ अपने डिफ़ॉल्ट पर लौट जाते थे। अब हर समूह सहेजने के बाद भी बना रहता है, और एक परीक्षण इसकी पुष्टि करता है।","changelog.3e59c181d02c":"<span class=\"release__meta\"><span class=\"release__ver\">v0.20.0</span><time class=\"release__date\" datetime=\"2026-07-20\">2026-07-20</time></span><span class=\"release__title\">सुरक्षा जाल</span>","changelog.245019914a17":"<strong>पूर्ववत।</strong> Ctrl+Z, या इतिहास की किसी पंक्ति पर “पूर्ववत करें”, दिखाता है कि सबसे नई कॉपी या मूव को उलटने से किन चीज़ों पर असर होगा, फिर उसे करता है। कॉपी की गई फ़ाइलें रीसायकल बिन या ट्रैश में जाती हैं, और केवल तभी जब वे अब भी कॉपी की गई सामग्री से मेल खाती हों।","changelog.6632a5f505b6":"<strong>रीसायकल बिन या ट्रैश में हटाना</strong>, और किसी मूव की गई फ़ाइल की मूल प्रति को हटाने के बजाय वहाँ भेजने का विकल्प।","changelog.8242fb20ac7f":"<strong>विफल पुनः प्रयास।</strong> किसी कार्य में विफल हुई फ़ाइलों को ही फिर से कॉपी करें, या उनकी सूची निर्यात करें।","changelog.6b92af518239":"<strong>मौजूदा फ़ाइलों के लिए दो नए विकल्प।</strong> केवल सामग्री अलग होने पर ओवरराइट करें, या एक जैसी होने पर छोड़ें और वरना पूछें।","changelog.dca682f75970":"<strong>निकालें।</strong> जिस ड्राइव पर किसी कार्य ने लिखा, उसे सुरक्षित रूप से हटाएँ।","changelog.e2eb082a0eff":"<strong>कॉपी के दौरान स्लीप नहीं।</strong> जब तक कोई भी कार्य चल रहा हो, कंप्यूटर जागता रहता है।","changelog.d2392c075c64":"<strong>चेकसम फ़ाइलें।</strong> पूरे फ़ोल्डर के लिए <code>.md5</code>, <code>.sha1</code>, <code>.sha256</code>, <code>.sha512</code>, <code>.b3</code> या <code>.sfv</code> फ़ाइलें बनाएँ, और उनमें सूचीबद्ध हर फ़ाइल जाँचने के लिए उनमें से किसी को विंडो पर छोड़ें।","changelog.95c1ab071772":"<strong>Windows की कॉपी को अपने हाथ में लें।</strong> चाहें तो Explorer के अपने कॉपी और पेस्ट को Freally File Manager के ज़रिए भेजें, एक क्लिक में वापसी के रास्ते के साथ। हर पेस्ट साधारण सिस्टम कॉपी या सत्यापित कॉपी का विकल्प देता है।","changelog.a20adfb45e43":"<strong>लाइसेंस अनुबंध।</strong> यह ऐप के पहली बार खुलने पर दिखाया जाता है।","changelog.be1a948a30a9":"<span class=\"release__meta\"><span class=\"release__ver\">v0.19.85</span><time class=\"release__date\" datetime=\"2026-07-01\">2026-07-01</time></span><span class=\"release__title\">लाइब्रेरी और बैकअप टूल</span>","changelog.d28e3ce211c4":"<strong>लाइब्रेरी।</strong> हर स्नैपशॉट की एक ही टाइमलाइन, यह दिखाते हुए कि कितना संग्रहित है और वह कितने का प्रतिनिधित्व करता है: चुने हुए फ़ोल्डरों का बैकअप लें, और किसी भी स्नैपशॉट को अपनी चुनी जगह पर पुनर्स्थापित करें।","changelog.eeb0847e8169":"<strong>संपीड़ित, सघन स्टोरेज।</strong> स्नैपशॉट संपीड़ित किए जा सकते हैं, और रखरखाव उस जगह को वापस लेता और सघन करता है जिसका अब कोई उपयोग नहीं करता, हर लंबा काम “कार्य” में दिखाते हुए।","changelog.c73e54bfcf32":"<strong>तुलना और रिपोर्ट।</strong> दो स्नैपशॉट की तुलना करें, और रिपॉज़िटरी के आँकड़े और चार्ट देखें।","changelog.f9c43f8de8b1":"<strong>रिपॉज़िटरी कुंजियाँ।</strong> एक रिपॉज़िटरी के लिए कई पासवर्ड, और एक रिकवरी कुंजी।","changelog.905de5db76c9":"<strong>प्रतिकृति।</strong> किसी रिपॉज़िटरी को दूसरी जगह कॉपी करें, केवल वही भेजते हुए जो दूसरी तरफ़ नहीं है।","changelog.ed05f802fa45":"<strong>दूसरे बैकअप टूल।</strong> <code>freally migrate</code> से restic, Borg या Kopia रिपॉज़िटरी लाएँ, और <code>freally export</code> से उसे वापस बाहर लिखें।","changelog.9310ff4d82b1":"पूरी समीक्षा में मिली पंद्रह समस्याएँ, जिनमें वे तरीक़े भी शामिल हैं जिनसे कोई बैकअप बिना बताए डेटा खो सकता था।","changelog.9124de6aa268":"<span class=\"release__meta\"><span class=\"release__ver\">v0.19.84</span><time class=\"release__date\" datetime=\"2026-06-27\">2026-06-27</time></span><span class=\"release__title\">पहली रिलीज़</span>","changelog.facf44888f54":"<strong>बाइट-दर-बाइट सटीक कॉपी और मूव</strong> हर सिस्टम के सबसे तेज़ रास्ते से, जिन फ़ाइल सिस्टम में यह सुविधा है उन पर तुरंत क्लोन के साथ, और किसी भी आकार के फ़ोल्डर मेमोरी भरे बिना प्रवाहित होते हुए।","changelog.36feaab53bd3":"<strong>कॉपी के बाद सत्यापन</strong> आठ चेकसम के साथ, CRC32 और xxHash3 से लेकर SHA-256 और BLAKE3 तक।","changelog.d269986b29b2":"किसी भी कार्य को <strong>रोकें, जारी रखें और रद्द करें</strong>, चुनें कि पहले से मौजूद फ़ाइलों का क्या हो, और अनुमतियों के कारण अस्वीकार हुई फ़ाइल का एडमिनिस्ट्रेटर अधिकारों के साथ पुनः प्रयास करें।","changelog.294162447b0a":"हर कॉपी की प्रगति के जर्नल से <strong>क्रैश या रीबूट के बाद फिर से शुरू</strong>।","changelog.59d391bd4f36":"<strong>इतिहास और कुल योग</strong>: हर कार्य दर्ज, फ़िल्टर करने योग्य, CSV के रूप में निर्यात करने योग्य और एक क्लिक में फिर से चलाने योग्य।","changelog.bcb57f6f639f":"<strong>फ़िल्टर</strong>: शामिल करने और बाहर रखने के पैटर्न, आकार, तारीख़ें और फ़ाइल एट्रिब्यूट।","changelog.e262b2471351":"<strong>दोतरफ़ा सिंक</strong> टकराव की पहचान के साथ, मिरर और योगदान मोड, और एक लाइव मिरर जो हर सहेजे गए बदलाव को सिंक करता है।","changelog.f299d8319e86":"<strong>गति सीमाएँ</strong>, स्थिर या किसी शेड्यूल पर।","changelog.7ba87a11a88a":"<strong>चुपचाप कुछ नहीं खोता</strong>: स्पार्स फ़ाइलें, वैकल्पिक डेटा स्ट्रीम, विस्तारित एट्रिब्यूट और इंटरनेट-से-डाउनलोड का निशान बने रहते हैं, और Windows पर लॉक की गई फ़ाइल स्नैपशॉट से कॉपी की जा सकती है।","changelog.a0a934ff3831":"<strong>आपका डेस्कटॉप</strong>: Windows, macOS और Linux पर राइट-क्लिक मेनू, कहीं से भी काम करने वाला पेस्ट शॉर्टकट, और एक ट्रे आइकन।","changelog.2180818af954":"<strong>एक फ़ाइल सर्वर</strong> WebDAV, HTTP, S3-संगत API या SFTP पर, बिना स्क्रीन वाले कंप्यूटरों के लिए <code>freally serve</code> के साथ।","changelog.d49f07823c77":"<strong><code>freally</code> कमांड लाइन</strong>, JSON-लाइनों वाले आउटपुट, प्रलेखित एग्ज़िट कोड और ऐसे कार्यों के साथ जिनकी योजना आप चलाने से पहले बना सकते हैं।","changelog.e50cd2fc0077":"<strong>यह धीमा क्यों है?</strong> एक बैज बताता है कि कॉपी को क्या रोक रहा है।","changelog.3d3204d8e967":"<strong>18 भाषाएँ</strong>, अरबी दाएँ से बाएँ।"};
